#!/usr/bin/env node
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");

const args = process.argv.slice(2);
function getArg(flag) {
  const idx = args.indexOf(flag);
  return idx !== -1 && idx + 1 < args.length ? args[idx + 1] : undefined;
}

const domain = getArg("--domain");
const feature = getArg("--feature");
const priority = getArg("--priority") || "high";
const epic = getArg("--epic") || "EPIC-BOOTSTRAP";
let taskId = getArg("--task-id");

if (!domain || !feature) {
  console.error(
    "Usage: new-ai-task-bundle.mjs --domain <domain> --feature <feature> [--priority <p>] [--epic <e>] [--task-id <id>]",
  );
  process.exit(1);
}

const manifestPath = join(repoRoot, ".ai", "operating-system.json");
if (!existsSync(manifestPath)) {
  throw new Error(`Missing operating system manifest at ${manifestPath}`);
}

const manifest = JSON.parse(readFileSync(manifestPath, "utf-8"));
const domains = Object.keys(manifest.domains);

if (!domains.includes(domain)) {
  throw new Error(`Unknown domain '${domain}'. Allowed values: ${domains.join(", ")}`);
}

if (!taskId) {
  const now = new Date();
  const ts = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}-${String(now.getHours()).padStart(2, "0")}${String(now.getMinutes()).padStart(2, "0")}${String(now.getSeconds()).padStart(2, "0")}`;
  taskId = `AI-${ts}`;
}

const ownerAgent = manifest.domains[domain].ownerAgent;
const taskDir = join(repoRoot, ".ai", "tasks", domain);
const integrationDir = join(repoRoot, ".ai", "reports", "integrations");
const taskPath = join(taskDir, `${taskId}.md`);
const jiraTemplatePath = join(repoRoot, "jira", "task-payload-template.json");
const linearTemplatePath = join(repoRoot, "linear", "issue-payload-template.json");

mkdirSync(taskDir, { recursive: true });
mkdirSync(integrationDir, { recursive: true });

const taskContent = `# ${taskId} - ${feature}

## Domain

${domain}

## Objective

Deliver ${feature} with controlled scope and auditable outputs.

## Scope

- Implement the approved change surface for ${domain}.
- Respect rules from docs/rules/domains/${domain}.md and docs/rules/global.md.
- Keep outputs compatible with the current architecture and governance gates.

## Acceptance criteria

- Task objective is implemented for ${domain}.
- Domain rules are respected.
- Tests, docs, PR metadata, and rollback notes are generated.
- Governance risks are explicit.

## Rules

- Owner agent: ${ownerAgent}
- Priority: ${priority}
- Epic: ${epic}

## Dependencies

- Diagnostic source
- Architecture review when cross-domain impact exists
- QA validation before release

## Test plan

- Generated by scripts/new-ai-test-plan.mjs

## Documentation updates

- Generated by scripts/new-ai-documentation-pack.mjs

## Rollout and rollback

- Must be defined before merge if the task affects production behavior.
`;

writeFileSync(taskPath, taskContent, "utf-8");

function expandTemplate(template, values) {
  let result = template;
  for (const [key, val] of Object.entries(values)) {
    result = result.replaceAll(`{{${key}}}`, val);
  }
  return result;
}

const replacements = {
  TASK_TITLE: feature,
  TASK_DESCRIPTION: `AI-generated task bundle for ${feature}`,
  DOMAIN: domain,
  OWNER_AGENT: ownerAgent,
  RISK_LEVEL: priority,
  ROLLBACK: "Revert branch and redeploy previous known-good state",
  PRIORITY: priority,
  PR_LINK: "",
};

const jiraContent = expandTemplate(readFileSync(jiraTemplatePath, "utf-8"), replacements);
const linearContent = expandTemplate(readFileSync(linearTemplatePath, "utf-8"), replacements);

const jiraPath = join(integrationDir, `${taskId}-jira.json`);
const linearPath = join(integrationDir, `${taskId}-linear.json`);

writeFileSync(jiraPath, jiraContent, "utf-8");
writeFileSync(linearPath, linearContent, "utf-8");

console.log(taskPath);
console.log(jiraPath);
console.log(linearPath);
